(() => {"use strict";const baseUrl=new URL(".",document.currentScript.src);const fetchText=async name=>{const response=await fetch(new URL(name,baseUrl),{cache:"no-cache"});if(!response.ok)throw new Error(`Не загружен ${name} (${response.status})`);return response.text()};const executeParts=async(names,sourceName)=>{const code=(await Promise.all(names.map(fetchText))).join("");(0,eval)(`${code}
//# sourceURL=${sourceName}`)};const loadScript=name=>new Promise((resolve,reject)=>{const script=document.createElement("script");script.src=new URL(name,baseUrl).href;script.onload=resolve;script.onerror=()=>reject(new Error(`Не загружен ${name}`));document.head.appendChild(script)});(async()=>{await executeParts(["maplibre.part-000.js","maplibre.part-001.js"],"maplibre.js");await loadScript("map-ui.js");await loadScript("map-page.js")})().catch(error=>{console.error(error);const status=document.getElementById("map-status");if(status){status.textContent=`Карта не загрузилась: ${error.message}`;status.dataset.failed="true"}})})();
